(function () {
    function init() {
        const container =
            document.getElementById('scroll-gallery') ||
            document.getElementById('infinite-scroll-gallery');

        if (!container || Util.isMobile()) {
            if (!container) console.warn('justified-gallery: container not found.');
            return;
        }

        // Phase 2: auto-detect structure — dateSection present → explore mode, else person mode
        const useExploreMode = !!container.querySelector('.dateSection');
        const rowSelector = useExploreMode ? '.dateSection .row' : '.row.image-group-padding';

        const config = {
            targetRowHeight: parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-target-row-height')) || 225,
            gap: parseInt(getComputedStyle(document.documentElement).getPropertyValue('--jg-gap')) || 4,
            justifyLastRow: false,
            resizeDebounce: 120,
            mutationDebounce: 80,
            maxRowHeightMultiplier: 1.4,
            minContainerWidthForFallback: 120,
            scrollBottomThreshold: 300
        };

        const debounce = (fn, wait) => {
            let t;
            return (...args) => { clearTimeout(t); t = setTimeout(() => fn.apply(this, args), wait); };
        };

        // Phase 3: cached container width — updated by ResizeObserver, used for full-width rows
        let cachedContainerWidth = 0;

        const itemAspectRatio = el => {
            const img = el.querySelector('img');
            if (!img) return 1;
            // Phase 1: data-aspect short-circuits all async image waiting
            if (img.dataset?.aspect) return +img.dataset.aspect || 1;
            if (img.hasAttribute('width') && img.hasAttribute('height')) {
                const w = +img.getAttribute('width'), h = +img.getAttribute('height');
                if (w > 0 && h > 0) return w / h;
            }
            return (img.naturalWidth && img.naturalHeight) ? img.naturalWidth / img.naturalHeight : 1;
        };

        const availableContentWidth = el => {
            // Person mode rows are always full-width — use cached container width
            if (!useExploreMode && cachedContainerWidth > 0) return cachedContainerWidth;

            // Explore mode: each section sizes to its own content width
            let w = Math.max(1, Math.floor(el.getBoundingClientRect().width));
            if (w < config.minContainerWidthForFallback) {
                const section = el.closest('.dateSection');
                if (section) {
                    const sRect = section.getBoundingClientRect();
                    const cs = getComputedStyle(section);
                    const fallback = Math.max(1, Math.floor(sRect.width - (parseFloat(cs.paddingLeft) || 0) - (parseFloat(cs.paddingRight) || 0)));
                    if (fallback > w + 8) w = fallback;
                }
            }
            return Math.min(w, Math.max(1, Math.floor(window.innerWidth - 32)));
        };

        const waitForSectionImages = async sectionEl => {
            const imgs = [...sectionEl.querySelectorAll('img')].filter(img => img.id?.startsWith('image'));
            if (!imgs.length) return;
            await Promise.all(imgs.map(img => {
                // Phase 1: data-aspect means we have all we need — no I/O required
                if (img.dataset?.aspect) return Promise.resolve();
                if (img.decode) return img.decode().catch(() => {});
                if (img.complete && img.naturalWidth) return Promise.resolve();
                return new Promise(res => { img.onload = img.onerror = res; });
            }));
        };

        const computeRowKey = (items, w) =>
            `${items.length}|${Math.round(w)}|${items.map(it => Math.round(it.aspect * 1000)).join(',')}`;

        // Phase 5: rows near the viewport get rAF, off-screen rows get idle/deferred
        const isNearViewport = el => {
            const rect = el.getBoundingClientRect();
            const buffer = 600;
            return rect.bottom > -buffer && rect.top < window.innerHeight + buffer;
        };

        async function layoutDateBody(dateBodyEl) {
            if (!dateBodyEl) return;

            const itemEls = [...dateBodyEl.querySelectorAll('.photo-thumbnail-container')];
            if (!itemEls.length) return;

            try { await waitForSectionImages(dateBodyEl); } catch {}

            const containerWidth = availableContentWidth(dateBodyEl);
            const items = itemEls.map(el => ({ el, aspect: itemAspectRatio(el) }));
            const currentKey = computeRowKey(items, containerWidth);
            // Skip if already settled with identical key
            if (dateBodyEl.dataset.jgKey === currentKey && dateBodyEl.dataset.jgSettled === 'true') return;

            for (const el of itemEls) {
                if (el.style.width || el.style.height || el.style.marginRight || el.style.marginBottom) {
                    el.style.width = el.style.height = el.style.marginRight = el.style.marginBottom = '';
                }
            }

            dateBodyEl.style.fontSize = '0';
            dateBodyEl.style.lineHeight = '0';

            const { gap, targetRowHeight: targetH } = config;
            const rows = [];
            let row = [], sum = 0;

            items.forEach((it, idx) => {
                row.push(it);
                sum += it.aspect;
                if (sum * targetH + (row.length - 1) * gap >= containerWidth || idx === items.length - 1) {
                    rows.push({ items: row.slice(), aspectSum: sum, isLast: idx === items.length - 1 });
                    row = []; sum = 0;
                }
            });

            const plans = rows.map(r => {
                const totalGap = (r.items.length - 1) * gap;
                let height;
                if (r.isLast && !config.justifyLastRow) {
                    height = targetH;
                    const totalW = r.items.reduce((s, it) => s + it.aspect * height, 0) + totalGap;
                    if (totalW > containerWidth) height = (containerWidth - totalGap) / r.aspectSum;
                } else {
                    height = (containerWidth - totalGap) / r.aspectSum;
                }
                height = Math.min(Math.max(1, height), Math.round(targetH * config.maxRowHeightMultiplier));

                let rounded = r.items.map(it => Math.round(it.aspect * height));
                let used = rounded.reduce((s, v) => s + v, 0);
                const discrepancy = containerWidth - totalGap - used;

                if (!r.isLast || config.justifyLastRow) {
                    if (discrepancy !== 0 && r.items.length > 0) {
                        const sign = discrepancy > 0 ? 1 : -1;
                        let rem = Math.abs(discrepancy), i = 0;
                        while (rem-- > 0) rounded[i++ % r.items.length] += sign;
                    }
                    used = rounded.reduce((s, v) => s + v, 0);
                    if (used + totalGap > containerWidth && used > 0) {
                        const scale = (containerWidth - totalGap) / used;
                        rounded = rounded.map(w => Math.max(1, Math.floor(w * scale)));
                    }
                } else {
                    if (used + totalGap > containerWidth && used > 0) {
                        const scale = (containerWidth - totalGap) / used;
                        rounded = rounded.map(w => Math.max(1, Math.floor(w * scale)));
                    }
                }
                return { rItems: r.items, height, widths: rounded, gap };
            });

            const doApply = () => {
                stopObserving();
                try {
                    plans.forEach(p => {
                        p.rItems.forEach((it, i) => {
                            it.el.style.width  = Math.max(1, Math.round(p.widths[i])) + 'px';
                            it.el.style.height = Math.max(1, Math.round(p.height)) + 'px';
                            it.el.style.marginRight  = i < p.rItems.length - 1 ? p.gap + 'px' : '0';
                            it.el.style.marginBottom = p.gap + 'px';
                        });
                    });
                    dateBodyEl.dataset.jgSettled = 'true';
                    dateBodyEl.dataset.jgKey = currentKey;
                } finally {
                    setTimeout(startObserving, 8);
                }
            };

            // Phase 5: prioritise visible rows; defer off-screen ones
            if (isNearViewport(dateBodyEl)) {
                requestAnimationFrame(doApply);
            } else if (window.requestIdleCallback) {
                requestIdleCallback(doApply, { timeout: 500 });
            } else {
                setTimeout(doApply, 100);
            }
        }

        const getRows = () => [...container.querySelectorAll(rowSelector)];

        const layoutAllSections = () => {
            getRows().forEach(row => {
                row.dataset.jgSettled = 'false';
                layoutDateBody(row);
            });
        };

        // Observer machinery with pending-row queue
        let mo = null, observing = false;
        const pendingRows = new Set();

        const startObserving = () => {
            if (!mo) mo = new MutationObserver(onMutations);
            if (!observing) {
                mo.observe(container, { childList: true, subtree: true });
                observing = true;
            }
            if (pendingRows.size) {
                const rows = [...pendingRows];
                pendingRows.clear();
                rows.forEach(r => r instanceof Element && layoutDateBody(r));
            }
        };

        const stopObserving = () => {
            if (mo && observing) { try { mo.disconnect(); } catch {} observing = false; }
        };

        const debouncedSchedule = debounce(rows => {
            rows.forEach(row => {
                if (row instanceof Element) {
                    row.dataset.jgSettled = 'false';
                    layoutDateBody(row);
                }
            });
        }, config.mutationDebounce);

        // Phase 4: skip known overlay/script nodes that can never contain rows
        const SKIP_TAGS = new Set(['SCRIPT', 'INPUT', 'STYLE']);
        const SKIP_CLASSES = ['thumbnail-tr', 'thumbnail-tl', 'thumbnail-br', 'thumbnail-bl',
                              'thumbnail-centered', 'overlayIconBackground', 'overlayIcon',
                              'mediaLink', 'lightGalleryIndexAnchor'];

        function findAffectedRow(node) {
            if (!(node instanceof Element)) return null;
            if (SKIP_TAGS.has(node.tagName)) return null;
            if (SKIP_CLASSES.some(c => node.classList.contains(c))) return null;

            if (node.classList.contains('dateSection') || node.classList.contains('dateContainer')) {
                return node.querySelector('.row');
            }
            if (node.matches?.(rowSelector)) return node;
            if (node.classList.contains('photo-thumbnail-container')) return node.closest(rowSelector);
            // Only recurse if node could plausibly contain rows
            const row = node.querySelector?.(rowSelector);
            return row || null;
        }

        let contentAppendedCallback = null;

        function onMutations(mutations) {
            const rowsToLayout = new Set();
            let newContent = false;

            for (const m of mutations) {
                if (m.type !== 'childList') continue;

                m.addedNodes.forEach(node => {
                    const row = findAffectedRow(node);
                    if (row) { rowsToLayout.add(row); newContent = true; }
                });

                m.removedNodes?.forEach(node => {
                    if (node instanceof Element && node.classList.contains('photo-thumbnail-container')) {
                        const row = node.closest(rowSelector);
                        if (row) rowsToLayout.add(row);
                    }
                });
            }

            if (!rowsToLayout.size) return;

            if (observing) {
                debouncedSchedule([...rowsToLayout]);
            } else {
                rowsToLayout.forEach(r => pendingRows.add(r));
            }

            if (newContent && contentAppendedCallback) {
                try { contentAppendedCallback(); } catch (e) { console.error('contentAppendedCallback error', e); }
            }
        }

        // Phase 3: ResizeObserver caches container CONTENT width and drives resize relayout.
        // contentRect.width excludes padding, matching what 'width:100%' children actually get.
        const containerContentWidth = () => {
            const cs = getComputedStyle(container);
            const pl = parseFloat(cs.paddingLeft) || 0;
            const pr = parseFloat(cs.paddingRight) || 0;
            return Math.max(1, Math.floor(container.getBoundingClientRect().width - pl - pr));
        };

        const debouncedLayoutAll = debounce(() => {
            cachedContainerWidth = containerContentWidth();
            getRows().forEach(r => r.dataset.jgSettled = 'false');
            layoutAllSections();
        }, config.resizeDebounce);

        const resizeObserver = new ResizeObserver(entries => {
            const w = Math.max(1, Math.floor(entries[0].contentRect.width));
            if (w !== cachedContainerWidth) {
                cachedContainerWidth = w;
                debouncedLayoutAll();
            }
        });
        resizeObserver.observe(container);

        // Near-bottom scroll catch-up: ensures rows appended at the tail get justified
        const debouncedScrollCatchUp = debounce(() => {
            const scrollY = window.scrollY || document.documentElement.scrollTop || 0;
            const viewportH = window.innerHeight || document.documentElement.clientHeight;
            const docH = Math.max(document.body.scrollHeight, document.documentElement.scrollHeight,
                                  document.body.offsetHeight, document.documentElement.offsetHeight);
            if (docH - (scrollY + viewportH) <= config.scrollBottomThreshold) layoutAllSections();
        }, 100);

        // Phase 6: scroll-anchor helper for bidirectional prepends
        // Caller wraps its prepend DOM mutations in fn(); scroll position is
        // corrected by the height delta after the next paint.
        function withScrollAnchor(fn) {
            const scrollY = window.scrollY || document.documentElement.scrollTop || 0;
            const oldHeight = document.documentElement.scrollHeight;
            fn();
            requestAnimationFrame(() => {
                const delta = document.documentElement.scrollHeight - oldHeight;
                if (delta > 0) window.scrollTo({ top: scrollY + delta, behavior: 'instant' });
            });
        }

        // Public API — both names for backward compatibility
        const api = {
            layoutAll: layoutAllSections,
            layoutDateBody,
            waitForSectionImages,
            withScrollAnchor,
            disconnectObserver: stopObserving,
            reconnectObserver: startObserving,
            setContentAppendedCallback: cb => { contentAppendedCallback = typeof cb === 'function' ? cb : null; }
        };
        window.ScrollJustifiedGallery = api;
        window.ScrollJustifiedGalleryInfinite = api;

        // Initial layout
        setTimeout(() => {
            cachedContainerWidth = containerContentWidth();
            const rows = getRows();
            if (!rows.length) { startObserving(); return; }
            Promise.all(rows.map(waitForSectionImages)).finally(() => {
                rows.forEach(row => { row.dataset.jgSettled = 'false'; layoutDateBody(row); });
                startObserving();
            });
        }, 20);

        window.addEventListener('resize', debouncedLayoutAll);
        window.addEventListener('scroll', debouncedScrollCatchUp, { passive: true });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
